record.field:
xmlid = "purchase_request_sarabun_todo.mail_activity_pr_returned_edit"
act_type = env.ref(xmlid, raise_if_not_found=False)
if act_type:
    for record in records:
        if not record.requested_by:
            continue
        record.activity_ids.filtered(
            lambda a: a.activity_type_id == act_type
            and a.user_id.id == record.requested_by.id
        ).unlink()
        record.activity_schedule(
            xmlid,
            summary="คำขอ พ.1 เลขที่ %s ถูกตีกลับ กรุณาแก้ไขและส่งหนังสือใหม่" % (record.name or ""),
            user_id=record.requested_by.id,
        )

